namespace sv_37b6986a516143dca5761b65089d22cf.Services;

public record Product(int Id, string Name, decimal Price, string Category, double Rating, bool InStock, string ImageUrl);
public record ProductFilter(List<string>? Categories, decimal? MinPrice, decimal? MaxPrice, bool InStockOnly);
public record PagedResult<T>(List<T> Items, int TotalCount, int Page, int PageSize);

public interface IProductService
{
    Task<PagedResult<Product>> SearchAsync(ProductFilter filter, string sortBy, int page, int pageSize);
    Task<List<string>> GetCategoriesAsync();
}

@namespace sv_37b6986a516143dca5761b65089d22cf.Components.Pages.Catalog

<div class="filter-panel">
    <h4>Filters</h4>

    <div class="filter-section">
        <h5>Categories</h5>
        @if (Categories is not null)
        {
            @foreach (var category in Categories)
            {
                <label class="filter-checkbox">
                    <input type="checkbox"
                           checked="@IsSelected(category)"
                           @onchange="@(e => ToggleCategory(category, (bool)e.Value!))" />
                    @category
                </label>
            }
        }
    </div>

    <div class="filter-section">
        <h5>Price Range</h5>
        <label>
            Min:
            <input type="number" min="0" step="0.01"
                   value="@MinPrice"
                   @onchange="@(e => MinPrice = ParseDecimal(e.Value))" />
        </label>
        <label>
            Max:
            <input type="number" min="0" step="0.01"
                   value="@MaxPrice"
                   @onchange="@(e => MaxPrice = ParseDecimal(e.Value))" />
        </label>
    </div>

    <div class="filter-section">
        <label class="filter-checkbox">
            <input type="checkbox"
                   checked="@InStockOnly"
                   @onchange="@(e => InStockOnly = (bool)e.Value!)" />
            In Stock Only
        </label>
    </div>

    <div class="filter-actions">
        <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
        <button class="btn btn-secondary" @onclick="ClearFilters">Clear Filters</button>
    </div>
</div>

@code {
    [Parameter] public List<string>? Categories { get; set; }
    [Parameter] public EventCallback<ProductFilter> OnApplyFilters { get; set; }

    private List<string> _selectedCategories = new();
    private decimal? MinPrice;
    private decimal? MaxPrice;
    private bool InStockOnly;

    private bool IsSelected(string category) => _selectedCategories.Contains(category);

    private void ToggleCategory(string category, bool selected)
    {
        if (selected && !_selectedCategories.Contains(category))
            _selectedCategories.Add(category);
        else if (!selected)
            _selectedCategories.Remove(category);
    }

    private async Task ApplyFilters()
    {
        var filter = new Services.ProductFilter(
            Categories: _selectedCategories.Count > 0 ? new List<string>(_selectedCategories) : null,
            MinPrice: MinPrice,
            MaxPrice: MaxPrice,
            InStockOnly: InStockOnly
        );
        await OnApplyFilters.InvokeAsync(filter);
    }

    private async Task ClearFilters()
    {
        _selectedCategories.Clear();
        MinPrice = null;
        MaxPrice = null;
        InStockOnly = false;
        await ApplyFilters();
    }

    private static decimal? ParseDecimal(object? value)
    {
        if (value is null || string.IsNullOrWhiteSpace(value.ToString()))
            return null;
        return decimal.TryParse(value.ToString(), out var result) ? result : null;
    }
}

@namespace sv_37b6986a516143dca5761b65089d22cf.Components.Pages.Catalog

<div class="product-card" @onclick="HandleCardClick">
    <div class="product-image" title="@Product.Name">
        <span>@Product.Name</span>
    </div>
    <div class="product-info">
        <h5 class="product-name">@Product.Name</h5>
        <p class="product-price">@Product.Price.ToString("C")</p>
        <p class="product-rating">@GetStarRating(Product.Rating)</p>
        @if (!Product.InStock)
        {
            <span class="badge out-of-stock">Out of Stock</span>
        }
        <button class="btn btn-cart"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public Services.Product Product { get; set; } = default!;
    [Parameter] public EventCallback<Services.Product> OnProductSelected { get; set; }
    [Parameter] public EventCallback<Services.Product> OnAddToCart { get; set; }

    private async Task HandleCardClick()
    {
        await OnProductSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        await OnAddToCart.InvokeAsync(Product);
    }

    private static string GetStarRating(double rating)
    {
        int fullStars = (int)Math.Round(rating);
        int emptyStars = 5 - fullStars;
        return new string('★', fullStars) + new string('☆', emptyStars);
    }
}

@namespace sv_37b6986a516143dca5761b65089d22cf.Components.Pages.Catalog

<div class="pagination-controls">
    <button class="btn btn-page" disabled="@(CurrentPage <= 1)" @onclick="PreviousPage">Previous</button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var pageNumber = i;
        <button class="btn btn-page @(pageNumber == CurrentPage ? "active" : "")"
                @onclick="@(() => GoToPage(pageNumber))">
            @pageNumber
        </button>
    }

    <button class="btn btn-page" disabled="@(CurrentPage >= TotalPages)" @onclick="NextPage">Next</button>
</div>

@code {
    [Parameter] public int CurrentPage { get; set; }
    [Parameter] public int TotalPages { get; set; }
    [Parameter] public EventCallback<int> OnPageChanged { get; set; }

    private async Task PreviousPage() => await GoToPage(CurrentPage - 1);
    private async Task NextPage() => await GoToPage(CurrentPage + 1);
    private async Task GoToPage(int page) => await OnPageChanged.InvokeAsync(page);
}

@page "/catalog"
@namespace sv_37b6986a516143dca5761b65089d22cf.Components.Pages.Catalog
@using sv_37b6986a516143dca5761b65089d22cf.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-layout">
    <aside class="catalog-sidebar">
        <ProductFilterPanel Categories="@_categories" OnApplyFilters="HandleApplyFilters" />
    </aside>

    <main class="catalog-main">
        @if (_loading)
        {
            <div class="catalog-loading">
                <p>Loading products...</p>
            </div>
        }
        else if (_error is not null)
        {
            <div class="catalog-error">
                <p>Error loading products: @_error</p>
                <button class="btn btn-primary" @onclick="LoadProducts">Retry</button>
            </div>
        }
        else if (_result is null || _result.Items.Count == 0)
        {
            <div class="catalog-empty">
                <p>No products found matching your criteria.</p>
            </div>
        }
        else
        {
            <div class="catalog-toolbar">
                <div class="sort-control">
                    <label>Sort by:</label>
                    <select @onchange="HandleSortChanged">
                        <option value="price_asc" selected="@(_sortBy == "price_asc")">Price: Low to High</option>
                        <option value="price_desc" selected="@(_sortBy == "price_desc")">Price: High to Low</option>
                        <option value="name_asc" selected="@(_sortBy == "name_asc")">Name: A-Z</option>
                        <option value="rating_desc" selected="@(_sortBy == "rating_desc")">Rating: Highest</option>
                    </select>
                </div>
                <span class="results-summary">
                    Showing @((_result.Page - 1) * _result.PageSize + 1)–@(Math.Min(_result.Page * _result.PageSize, _result.TotalCount)) of @_result.TotalCount products
                </span>
            </div>

            <div class="product-grid">
                @foreach (var product in _result.Items)
                {
                    <ProductCard Product="@product"
                                 OnProductSelected="HandleProductSelected"
                                 OnAddToCart="HandleAddToCart" />
                }
            </div>

            <Pagination CurrentPage="@_result.Page"
                        TotalPages="@TotalPages"
                        OnPageChanged="HandlePageChanged" />
        }
    </main>
</div>

@code {
    [Parameter] public EventCallback<Product> OnProductSelected { get; set; }

    private List<string>? _categories;
    private PagedResult<Product>? _result;
    private ProductFilter _filter = new(null, null, null, false);
    private string _sortBy = "price_asc";
    private int _currentPage = 1;
    private const int PageSize = 12;
    private bool _loading = true;
    private string? _error;

    private int TotalPages => _result is null ? 0 : (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _categories = await ProductService.GetCategoriesAsync();
            await LoadProducts();
        }
        catch (Exception ex)
        {
            _error = ex.Message;
            _loading = false;
        }
    }

    private async Task LoadProducts()
    {
        _loading = true;
        _error = null;
        StateHasChanged();

        try
        {
            _result = await ProductService.SearchAsync(_filter, _sortBy, _currentPage, PageSize);
        }
        catch (Exception ex)
        {
            _error = ex.Message;
        }
        finally
        {
            _loading = false;
        }
    }

    private async Task HandleApplyFilters(ProductFilter filter)
    {
        _filter = filter;
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandleSortChanged(ChangeEventArgs e)
    {
        _sortBy = e.Value?.ToString() ?? "price_asc";
        _currentPage = 1;
        await LoadProducts();
    }

    private async Task HandlePageChanged(int page)
    {
        _currentPage = page;
        await LoadProducts();
    }

    private async Task HandleProductSelected(Product product)
    {
        await OnProductSelected.InvokeAsync(product);
    }

    private Task HandleAddToCart(Product product)
    {
        // Placeholder for add-to-cart logic
        return Task.CompletedTask;
    }
}

.catalog-layout {
    display: flex;
    gap: 1.5rem;
    padding: 1rem;
}

.catalog-sidebar {
    flex: 0 0 25%;
    max-width: 25%;
}

.catalog-main {
    flex: 1;
    min-width: 0;
}

.catalog-loading,
