    border: 1px solid #ced4da;
    border-radius: 0.25rem;
}

.results-summary {
    color: #6c757d;
    font-size: 0.9rem;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.25rem;
    margin-bottom: 1.5rem;
}

::deep .filter-panel {
    padding: 1rem;
    border: 1px solid #dee2e6;
    border-radius: 0.5rem;
    background: #f8f9fa;
}

::deep .filter-panel h4 {
    margin-bottom: 1rem;
}

