}

::deep .product-price {
    font-weight: 600;
    color: #198754;
    margin-bottom: 0.25rem;
}

::deep .product-rating {
    color: #ffc107;
    margin-bottom: 0.4rem;
}

::deep .badge.out-of-stock {
    display: inline-block;
    background: #dc3545;
    color: white;
    font-size: 0.75rem;
    padding: 0.2rem 0.5rem;
    border-radius: 0.25rem;
    margin-bottom: 0.4rem;
}

::deep .btn {
    padding: 0.375rem 0.75rem;
    border: none;
    border-radius: 0.25rem;
    cursor: pointer;
    font-size: 0.875rem;
}

::deep .btn:disabled {
    opacity: 0.6;
    cursor: not-allowed;
}

::deep .btn-primary {
    background: #0d6efd;
    color: white;
}

::deep .btn-secondary {
    background: #6c757d;
    color: white;
}

::deep .btn-cart {
    width: 100%;
    background: #0d6efd;
    color: white;
    margin-top: 0.5rem;
}

::deep .pagination-controls {
    display: flex;
    justify-content: center;
    align-items: center;
    gap: 0.4rem;
    padding: 1rem 0;
}

::deep .btn-page {
    background: #fff;
    border: 1px solid #dee2e6;
    color: #212529;
    min-width: 2.2rem;
    text-align: center;
}

::deep .btn-page.active {
    background: #0d6efd;
    color: white;
    border-color: #0d6efd;
}

