@namespace sv_37b6986a516143dca5761b65089d22cf.Components.Pages.Catalog

<div class="product-card" @onclick="HandleCardClick">
    <div class="product-image" title="@Product.Name">
        <span>@Product.Name</span>
    </div>
    <div class="product-info">
        <h5 class="product-name">@Product.Name</h5>
        <p class="product-price">@Product.Price.ToString("C")</p>
        <p class="product-rating">@GetStarRating(Product.Rating)</p>
        @if (!Product.InStock)
        {
            <span class="badge out-of-stock">Out of Stock</span>
        }
        <button class="btn btn-cart"
                disabled="@(!Product.InStock)"
                @onclick="HandleAddToCart"
                @onclick:stopPropagation="true">
            Add to Cart
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public Services.Product Product { get; set; } = default!;
    [Parameter] public EventCallback<Services.Product> OnProductSelected { get; set; }
    [Parameter] public EventCallback<Services.Product> OnAddToCart { get; set; }

    private async Task HandleCardClick()
    {
        await OnProductSelected.InvokeAsync(Product);
    }

    private async Task HandleAddToCart()
    {
        await OnAddToCart.InvokeAsync(Product);
    }

    private static string GetStarRating(double rating)
    {
        int fullStars = (int)Math.Round(rating);
        int emptyStars = 5 - fullStars;
        return new string('★', fullStars) + new string('☆', emptyStars);
    }
}

