@namespace sv_37b6986a516143dca5761b65089d22cf.Components.Pages.Catalog

<div class="pagination-controls">
    <button class="btn btn-page" disabled="@(CurrentPage <= 1)" @onclick="PreviousPage">Previous</button>

    @for (int i = 1; i <= TotalPages; i++)
    {
        var pageNumber = i;
        <button class="btn btn-page @(pageNumber == CurrentPage ? "active" : "")"
                @onclick="@(() => GoToPage(pageNumber))">
            @pageNumber
        </button>
    }

    <button class="btn btn-page" disabled="@(CurrentPage >= TotalPages)" @onclick="NextPage">Next</button>
</div>

@code {
    [Parameter] public int CurrentPage { get; set; }
    [Parameter] public int TotalPages { get; set; }
    [Parameter] public EventCallback<int> OnPageChanged { get; set; }

    private async Task PreviousPage() => await GoToPage(CurrentPage - 1);
    private async Task NextPage() => await GoToPage(CurrentPage + 1);
    private async Task GoToPage(int page) => await OnPageChanged.InvokeAsync(page);
}

