@page "/catalog"
@namespace sv_37b6986a516143dca5761b65089d22cf.Components.Pages.Catalog
@using sv_37b6986a516143dca5761b65089d22cf.Services
@inject IProductService ProductService
@rendermode InteractiveServer

<PageTitle>Product Catalog</PageTitle>

<div class="catalog-layout">
    <aside class="catalog-sidebar">
        <ProductFilterPanel Categories="@_categories" OnApplyFilters="HandleApplyFilters" />
    </aside>

    <main class="catalog-main">
        @if (_loading)
        {
            <div class="catalog-loading">
                <p>Loading products...</p>
            </div>
        }
